def is_inside(pts,q):
    n=len(pts)
    if n<3: return False
    crosses=0
    for i in range(n):
        a=pts[i]; b=pts[(i+1)%n]
        ra,ca=a; rb,cb=b
        if min(ra,rb)<q[0]<max(ra,rb) and ((ca<q[1])!=(cb<q[1])):
