def strict_inside_hull(pts,q):
    if len(pts)<3: return False
    def cross(o,a,b): return (a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0])
    P=sorted(set(map(tuple,pts))); h=[]
    for a in P:
        while len(h)>=2 and cross(h[-2],h[-1],a)<=0: h.pop()
        h.append(a)
    for a in reversed(P):
        while len(h)>=2 and cross(h[-2],h[-1],a)<=0: h.pop()
        h.append(a)
    h=h[:-1]
    def ccrossings(o):
        n=len(h); res=0
        for j in range(n):
            a=h[j]; b_=h[(j+1)%n]
            if min(a[0],b_[0])<=o[0]<max(a[0],b_[0]) and ((a[1]<o[1])!=(b_[1]<o[1])): res+=1
        return res%2==1
    # try offsets toward each of 8 dirs; interior iff at least one offset crosses odd edges? Better: check against epsilon on both sides
    ok=False
    for sgn_r in [1,-1]:
        for sgn_c in [1,-1]:
            o=(q[0]+sgn_r*1e-9,q[1]+sgn_c*1e-9)
            if ccrossings(o): ok=True; break
        if ok: break
    return ok
